// All 130 Fire in the Lake cards. Text is copied from the 2018 Playbook ("Event Text, Tips, and
// Background"): titles, faction order, period and 2nd Ed marks are as printed on the card list.
// Unshaded/shaded paragraphs are verbatim (hyphenation from the PDF removed). Cards printed with a
// single text (McNamara Line, Bombing Pause, Honolulu Conference, MACV, Light at the End of the
// Tunnel, Tunnel Rats, Binh Duong, Typhoon Kate) have it in `unshaded`, `shaded` is '' and `dual` is
// true. Pivotal Events (121-124) keep their full text (precondition, effect, restrictions) in
// `unshaded`. Coup cards (125-130) keep the leader effect plus Coup/Monsoon text in `unshaded`.
import type { CardDef, Faction } from '../core/types';

export interface CardDefX extends CardDef {
  tips?: string;                 // Playbook implementation tips
  secondEd?: boolean;            // card text updated for the 2nd Edition
  edition?: string;              // '2nd Ed' when secondEd (read by the card panel)
  dual?: boolean;                // single printed text (no separate shaded side)
  cap_faction?: Faction;         // owner of the CAPABILITY marker
  momentum_unshaded?: boolean;   // the unshaded text is a MOMENTUM effect
  momentum_shaded?: boolean;     // the shaded text is a MOMENTUM effect
}

const F: Record<string, Faction> = { U: 'US', A: 'ARVN', N: 'NVA', V: 'VC' };
const CAPF: Record<string, Faction> = { US: 'US', NVA: 'NVA', ARVN: 'ARVN', VC: 'VC' };

// [id, title, order, period, 2nd Ed, capability owner, momentum bits (1 unshaded, 2 shaded), dual, unshaded, shaded, tips]
type Row = [number, string, string, string, number, string, number, number, string, string, string];

