function build(r: Row): CardDefX {
  const [id, title, ord, period, second, capf, mom, dual, unshaded, shaded, tips] = r;
  const c: CardDefX = {
    id, title, coup: id >= 125, order: [...ord].map((ch) => F[ch]), unshaded, shaded,
  };
  if (period) c.period = period as CardDef['period'];
  if (second) { c.secondEd = true; c.edition = '2nd Ed'; }
  if (capf) { c.capability = true; c.cap_faction = CAPF[capf]; }
  if (mom) {
    c.momentum = true;
    if (mom & 1) c.momentum_unshaded = true;
    if (mom & 2) c.momentum_shaded = true;
  }
  if (dual) c.dual = true;
  if (id >= 121 && id <= 124) c.pivotal = c.order[0];
  if (id >= 125 && id <= 128) c.leader = true;
  if (tips) c.tips = tips;
  return c;
}

export const CARDS: CardDefX[] = ROWS.map(build);
export const CARD: Record<number, CardDefX> = Object.fromEntries(CARDS.map((c) => [c.id, c]));
